cd /tmp/djgit && python - <<'EOF' 2>&1 | tail -40
import json,subprocess,re
def g(*a):
    return subprocess.run(['git']+list(a),cwd='/tmp/djgit',capture_output=True,text=True).stdout
def norm(s):
    return re.sub(r'\s+',' ',s.strip().rstrip('.` ')).lower()
# main commits after base
BASE='b23216d9d0ee'
out=g('log','--format=%H%x09%s',BASE+'..main')
main=[l.split('\t',1) for l in out.strip().split('\n') if '\t' in l]
bysubj={}
for sha,subj in main: bysubj.setdefault(norm(subj),[]).append(sha)

rm=json.load(open('/workspace/requirements/.rename_map.json'))
result={}; probs=[]
for k,v in rm.items():
    pr=k[:-5]; slug=v[:-5]
    mb=g('merge-base','main','refs/prs/'+pr).strip()
    subs=[l for l in g('log','--reverse','--format=%s',mb+'..refs/prs/'+pr).strip().split('\n') if l]
    shas=[]
    for s in subs:
        c=bysubj.get(norm(s))
        if c and len(c)==1: shas.append(c[0])
        elif c: shas.append(c[-1]); probs.append((slug,'multi',s))
        else: probs.append((slug,'nomatch',s))
    result[slug]={'pr':pr,'subjects':subs,'shas':shas}
json.dump(result,open('/tmp/prmap.json','w'),indent=1)
print("total",len(result))
print("multi-commit PRs:",sum(1 for v in result.values() if len(v['subjects'])>1))
print("problems",len(probs))
for p in probs: print(p)
EOF

cd /tmp/djgit && python - <<'EOF' 2>&1 | tail -30
import json,subprocess,re,os,yaml,difflib
def g(*a): return subprocess.run(['git']+list(a),cwd='/tmp/djgit',capture_output=True,text=True).stdout
def norm(s): return re.sub(r'\s+',' ',s.strip().rstrip('.` ')).lower()
BASE='b23216d9d0ee'
main=[l.split('\t',1) for l in g('log','--format=%H%x09%s',BASE+'..main').strip().split('\n') if '\t' in l]
bysubj={}
for sha,subj in main: bysubj.setdefault(norm(subj),[]).append(sha)
keys=list(bysubj)
pm=json.load(open('/tmp/prmap.json'))
final={}; unresolved=[]
for fn in sorted(f for f in os.listdir('/workspace/requirements') if f.endswith('.yaml')):
    slug=fn[:-5]
    title=yaml.safe_load(open('/workspace/requirements/'+fn))['title']
    e=pm[slug]
    shas=[]; ok=True
    for s in e['subjects']:
        c=bysubj.get(norm(s))
        if c: shas.append(c[-1])
        else:
            close=difflib.get_close_matches(norm(s),keys,n=1,cutoff=0.62)
            if close: shas.append(bysubj[close[0]][-1])
            else: ok=False
    # also try title
    tc=bysubj.get(norm(title))
    if not ok or not shas:
        if tc: shas=[tc[-1]]; ok=True
        else:
            close=difflib.get_close_matches(norm(title),keys,n=1,cutoff=0.7)
            if close: shas=[bysubj[close[0]][-1]]; ok=True
    if ok and shas:
        final[slug]={'pr':e['pr'],'shas':shas}
    else:
        unresolved.append((slug,title,e['subjects']))
json.dump(final,open('/tmp/final_map.json','w'),indent=1)
print("resolved",len(final),"unresolved",len(unresolved))
for u in unresolved: print("UNRESOLVED",u)
# print multi
for k,v in final.items():
    if len(v['shas'])>1: print("MULTI",k,len(v['shas']))
EOF
